    s1_c7_refs_list: `<li><a href="#" data-modal="modal-ref-pardubice-bydleni">Strategie bydlení města Pardubice</a></li><li>Analýza absorpční kapacity bytového fondu obcí v rámci IPRÚ Mladá Boleslav</li>`,
